document.addEventListener('DOMContentLoaded',async()=>{const list=document.querySelector('#news-list');if(!list)return;try{const items=await fetch('data/news.json').then(r=>r.json());const render=cat=>{const filtered=cat==='ALL'?items:items.filter(n=>n.category===cat);list.innerHTML=filtered.map(n=>`<a class="news-item" href="news-detail.html?id=${encodeURIComponent(n.id)}"><time class="meta">${n.date}</time><span class="meta category">${n.category}</span><h3>${n.title}</h3><span class="mark" aria-hidden="true">＋</span></a>`).join('')||'<p class="empty-state">該当するニュースはありません。</p>'};document.querySelectorAll('.filter').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.filter').forEach(x=>x.classList.remove('active'));b.classList.add('active');render(b.dataset.filter)}));render('ALL')}catch{list.innerHTML='<p class="empty-state">ニュースを読み込めませんでした。</p>'}});
